export function getIllustrationComponent(name: string): React.ComponentType | null {
  const modId = ILLUSTRATION_MODULE_IDS[name];
  if (!modId) return null;
  const mod = requireModule(modId);
  if (!mod) return null;
  return mod.default || Object.values(mod).find((v) => typeof v === "function") || null;
}
